pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 lockTime, uint256 putAmount, uint256 minSum, uint256 collectAmount) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        vm.assume(putAmount > 0);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Put{value: putAmount}(lockTime) {} catch { return; }
        uint256 beforeUnlock;
        uint256 beforeBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeBalance = __r1; } catch { return; }
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        uint256 afterUnlock;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBalance = __r1; } catch { return; }
        assertTrue(collectReverted
                ? afterBalance == beforeBalance
                : afterBalance <= beforeBalance);
    }

    function testFuzz_run(uint256 lockTime, uint256 putAmount, uint256 minSum, uint256 collectAmount) public {
        _run(lockTime, putAmount, minSum, collectAmount);
    }

    receive() external payable {}
}
